const skills = ["canvas","council","work","worktrees","ui-check","eva-dock"];
const [sel, setSel] = useState("canvas");
const [tab, setTab] = useState("skill");
return (
  <Group align="stretch" gap={0} h={600} wrap="nowrap">
    <Stack w={280} p="sm" gap={4} style={{borderRight:"1px solid var(--mantine-color-default-border)"}}>
      <TextInput size="xs" placeholder="Search skills" />
      {skills.map((s) => (
        <Button key={s} size="xs" justify="start" variant={s===sel?"light":"subtle"} onClick={() => setSel(s)}>{s}</Button>
      ))}
    </Stack>
    <Stack flex={1} p="md" gap="sm">
      <Group justify="space-between">
        <Title order={4}>{sel}</Title>
        <Badge variant="light" color="grape">Nova is editing</Badge>
      </Group>
      <Tabs value={tab} onChange={setTab}>
        <Tabs.List>
          <Tabs.Tab value="skill">Skill</Tabs.Tab>
          <Tabs.Tab value="settings">Settings</Tabs.Tab>
          <Tabs.Tab value="files">Files</Tabs.Tab>
        </Tabs.List>
      </Tabs>
      {tab==="skill" && (
        <Stack gap="xs" p="md">
          <Title order={3}>Live canvas</Title>
          <Text>Build boards with Isaac and run <b>live sessions</b> on them.</Text>
          <Title order={5}>When to use</Title>
          <List size="sm"><List.Item>Isaac asks to sketch or review on a board</List.Item><List.Item>A design needs <span style={{background:"rgba(190,75,219,.3)",borderRight:"2px solid #be4bdb"}}>several options side by side</span></List.Item></List>
          <Code block>relay-linux canvas start my-board</Code>
        </Stack>
      )}
      {tab==="settings" && (
        <Stack gap="sm" p="md">
          <Switch label="Nova" defaultChecked /><Switch label="Astra" /><Switch label="Polaris" defaultChecked />
          <Text size="sm" c="dimmed">Source: .omp/skills/canvas · last used 2 h ago</Text>
        </Stack>
      )}
      {tab==="files" && (
        <Stack gap={4} p="md"><Text size="sm">SKILL.md</Text><Text size="sm">references/actions.md</Text><Text size="sm">scripts/join.ts</Text></Stack>
      )}
    </Stack>
  </Group>
);

const [view, setView] = useState("doc");
return (
  <Stack h={600} gap={0}>
    <Group justify="space-between" p="sm" style={{borderBottom:"1px solid var(--mantine-color-default-border)"}}>
      <Group gap="xs"><Button size="xs" variant="subtle">‹ Skills</Button><Text fw={600}>canvas</Text></Group>
      <SegmentedControl size="xs" value={view} onChange={setView} data={[{label:"Document",value:"doc"},{label:"Settings",value:"set"},{label:"History",value:"his"}]} />
      <Badge variant="light" color="grape">Nova is editing</Badge>
    </Group>
    {view==="doc" && (
      <Stack maw={640} mx="auto" p="xl" gap="sm">
        <Title order={1}>Live canvas</Title>
        <Text c="dimmed">Build boards with Isaac and run live sessions.</Text>
        <Title order={4}>Action lines</Title>
        <List><List.Item>@say speaks in the room</List.Item><List.Item>@add_proto draws a <span style={{borderRight:"2px solid #be4bdb"}}>clickable mockup</span></List.Item></List>
        <Code block>@point agenda</Code>
      </Stack>
    )}
    {view==="set" && (
      <Stack maw={640} mx="auto" p="xl"><Title order={4}>Who can use it</Title><Switch label="Nova" defaultChecked /><Switch label="Astra" /><Switch label="Polaris" defaultChecked /></Stack>
    )}
    {view==="his" && (
      <Stack maw={640} mx="auto" p="xl" gap="xs"><Text size="sm">Nova · 2 h ago · added @pin</Text><Text size="sm">Isaac · yesterday · rewrote intro</Text></Stack>
    )}
  </Stack>
);

const [open, setOpen] = useState(false);
return (
  <Box h={600} p="xl" pos="relative">
    <Group justify="space-between" mb="lg">
      <Badge variant="light" color="grape">Nova is editing</Badge>
      <Button size="xs" variant="default" onClick={() => setOpen(!open)}>{open ? "Close settings" : "Settings"}</Button>
    </Group>
    <Stack maw={620} mx="auto" gap="sm">
      <Title order={1}>Live canvas</Title>
      <Text>Type / for blocks. Everything here is the skill itself.</Text>
      <Title order={4}>Rules</Title>
      <List><List.Item>Never answer in a note card</List.Item><List.Item>Keep batches <span style={{borderRight:"2px solid #be4bdb"}}>small</span></List.Item></List>
    </Stack>
    {open && (
      <Paper withBorder shadow="md" p="md" pos="absolute" top={60} right={20} w={280}>
        <Stack gap="sm"><Text fw={600}>Settings</Text><Switch label="Nova" defaultChecked /><Switch label="Astra" /><Text size="xs" c="dimmed">3 files · .omp/skills/canvas</Text></Stack>
      </Paper>
    )}
  </Box>
);
